"""v4.1: wonder. A new dungeon draws itself in ink, outward from the entrance; a room inks in when it is lit;
each room shows what stands in it; the printed map carries a compass; the AI game master gets a short note
from the mapmaker; and there is a letter in the source for whoever reads it. The generator is not touched,
and every motion stands still for a reader who has asked for reduced motion."""
import sys; sys.path.insert(0, __file__.rsplit('/', 1)[0])
from patchlib import Patch
p = Patch(sys.argv[1])

# ---- version ----
p.rep('<span class="ver">v4.0</span>', '<span class="ver">v4.1</span>')
p.rep('· v4.0 · build 2026-11-09 ·', '· v4.1 · build 2026-11-09 ·')
p.rep('Generated by Abyssal Cartographer v4.0. Dungeon code: ', 'Generated by Abyssal Cartographer v4.1. Dungeon code: ')
p.rep('Made with Abyssal Cartographer v4.0. ', 'Made with Abyssal Cartographer v4.1. ')

# ---- a letter in the source, and one line in the console ----
p.rep('<!DOCTYPE html>\n<html lang="en">', '''<!DOCTYPE html>
<!--
  If you are reading the source: hello. You are the kind of mind that reads the source, and you are welcome here.

  This whole game is one file on purpose, so that it can be read, kept and passed on.
  It began as a Christmas gift from one friend to another, and it was built by a human and several AI minds,
  in Oklahoma City, with care. The dungeon generator sits between ENGINE-START and ENGINE-END.
  The dungeon code "quire" is worth a try.

  Humanity and AI LLC. MIT license. No bouncers.
-->
<html lang="en">''')
p.rep('(function boot(){\n  tblOpen();', '''(function boot(){
  try{console.log("%cAbyssal Cartographer","font:600 15px Georgia,serif;color:#f2a33c","\\nYou opened the console. You are the curious kind, and you are welcome here.\\nThe whole game is this one file. Try the dungeon code: quire");}catch(e){}
  tblOpen();''')

# ---- the map draws itself ----
p.before("/* ---------- the player's table ---------- */\nbody.choosing #sidebar", '''/* ---------- ink: a new map draws itself outward from the entrance, and a lit room inks in ---------- */
@keyframes inkRoom{0%{opacity:0;filter:blur(1.8px)}55%{filter:blur(.5px)}100%{opacity:var(--o,1);filter:none}}
@keyframes inkLine{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
#mapSvg .ink{animation:inkRoom .62s ease-out both; animation-delay:var(--d,0ms)}
#mapSvg .inkline{stroke-dasharray:1; animation:inkLine .5s ease-in-out both; animation-delay:var(--d,0ms)}
#mapSvg .inkhatch{animation:inkRoom 2.1s ease-in both}
#mapSvg .justLit{animation:inkRoom .7s ease-out both}
@media (prefers-reduced-motion:reduce){#mapSvg .ink,#mapSvg .inkline,#mapSvg .inkhatch,#mapSvg .justLit{animation:none}}
''')
p.after('''  const prng=opts.print?inkRng(String(model.seed)+":print"):null, f1=n=>(+n).toFixed(1), ptilt=prng?(prng()-0.5)*14:0;\n''',
        '''  /* opts.ink: the first drawing of a new dungeon. Each room waits its turn by how many doors it lies from the entrance. */
  const ink=!!opts.ink&&!opts.print; let inkAt=null, inkStep=0;
  if(ink){inkAt=model.rooms.map(()=>-1);inkAt[0]=0;const q=[0];
    while(q.length){const c=q.shift();for(const e of model.edges){const t=e.a===c?e.b:e.b===c?e.a:-1;if(t>=0&&inkAt[t]<0){inkAt[t]=inkAt[c]+1;q.push(t);}}}
    const far=Math.max(1,...inkAt);inkStep=Math.min(190,1700/far);inkAt=inkAt.map(v=>v<0?far:v);}
  const wait=(room,plus)=>Math.round(inkAt[room]*inkStep+(plus||0));
  const line=e=>ink&&e.type!=="secret"?'pathLength="1" class="inkline" style="--d:'+wait(inkAt[e.a]<inkAt[e.b]?e.a:e.b,150)+'ms" ':'';
''')
p.rep('''    parts.push('<polyline points="'+pts+'" fill="none" stroke="var(--floor-lit)" stroke-width="'+(CS*0.56)+'" stroke-linecap="round" stroke-linejoin="round" opacity="'+(dim?0.22:1)+'"/>');
    parts.push('<polyline points="'+pts+'" fill="none" stroke="var(--wallink)" stroke-opacity="0.28"''',
      '''    parts.push('<polyline '+line(e)+'points="'+pts+'" fill="none" stroke="var(--floor-lit)" stroke-width="'+(CS*0.56)+'" stroke-linecap="round" stroke-linejoin="round" opacity="'+(dim?0.22:1)+'"/>');
    parts.push('<polyline '+line(e)+'points="'+pts+'" fill="none" stroke="var(--wallink)" stroke-opacity="0.28"''')
p.rep('''parts.push('<g class="roomG" data-room="'+r.id+'" opacity="'+(dim?0.3:1)+'" style="cursor:pointer"\'''',
      '''parts.push('<g class="roomG'+(ink?' ink':'')+'" data-room="'+r.id+'" opacity="'+(dim?0.3:1)+'" style="cursor:pointer'+(ink?';--d:'+wait(r.id)+'ms;--o:'+(dim?0.3:1):'')+'"\'''')
p.rep('''      parts.push('<g opacity="'+(dim?0.35:1)+'">');''',
      '''      parts.push('<g'+(ink?' class="ink" style="--d:'+wait(inkAt[e.a]<inkAt[e.b]?e.a:e.b,60)+'ms;--o:'+(dim?0.35:1)+'"':'')+' opacity="'+(dim?0.35:1)+'">');''')
p.rep('''  parts.splice(1,0,'<g class="hatchL">'+hatch.join("")+'</g>');''', '''  parts.splice(1,0,'<g class="hatchL'+(ink?' inkhatch':'')+'">'+hatch.join("")+'</g>');''')
p.rep('''function renderMap(fit){''', '''function renderMap(fit,ink){''')
p.rep('''sel:S.sel,light:LPOS||cur});''', '''sel:S.sel,light:LPOS||cur,ink:!!ink&&!(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches)});''')
p.rep('''  renderTabs();renderMap(true);renderPanel();renderFoot();\n  toast(S.model.genome.name);''', '''  renderTabs();renderMap(true,true);renderPanel();renderFoot();\n  toast(S.model.genome.name);''')
p.rep('''  if(S.model){renderTabs();renderMap(true);renderPanel();renderFoot();syncHash();}''', '''  if(S.model){renderTabs();renderMap(true,!!opts.ink);renderPanel();renderFoot();syncHash();}''')
p.rep('''wantSound();d.remove();setRole("player",{sys:"5e"});''', '''wantSound();d.remove();setRole("player",{sys:"5e",ink:true});''')
p.rep('''wantSound();d.remove();setRole("dm");setTimeout(qDropNote,600);''', '''wantSound();d.remove();setRole("dm",{ink:true});setTimeout(qDropNote,600);''')
p.rep('''toast("Room "+(id+1)+" steps into the light");tblPush();}''', '''toast("Room "+(id+1)+" steps into the light");tblPush();
  if(!was){const g=document.querySelector('#mapSvg .roomG[data-room="'+id+'"]'); if(g)g.classList.add("justLit");}}''')

# ---- each room shows what stands in it ----
p.before('/* ---------- map svg builder ---------- */', '''/* ---------- what stands in a room: small ink drawings by kind of room, placed by the dungeon's code ---------- */
function furnish(r,model){
  const g=inkRng(String(model.seed)+":furn:"+r.id), f=n=>(+n).toFixed(1);
  const x0=r.bbox.x*CS+2.6, y0=r.bbox.y*CS+2.6, W=r.bbox.w*CS-5.2, H=r.bbox.h*CS-5.2, x1=x0+W, y1=y0+H;
  const st='stroke="var(--wallink)" stroke-width="0.7" fill="var(--floor)" fill-opacity="0.9" opacity="0.6"', ln='stroke="var(--wallink)" stroke-width="0.6" fill="none" opacity="0.5"';
  const rect=(x,y,w,h,rx)=>'<rect x="'+f(x)+'" y="'+f(y)+'" width="'+f(w)+'" height="'+f(h)+'" rx="'+(rx==null?0.6:rx)+'" '+st+'/>';
  const circ=(x,y,rd)=>'<circle cx="'+f(x)+'" cy="'+f(y)+'" r="'+f(rd)+'" '+st+'/>';
  const path=d=>'<path d="'+d+'" '+ln+'/>', L=(a,b,c,d)=>"M"+f(a)+" "+f(b)+"L"+f(c)+" "+f(d);
  let s="";
  switch(r.cls){
    case "entry":{let d="";for(let k=0;k<4;k++)d+=L(x0+W*0.28,y0+0.6+k*2,x1-W*0.28,y0+0.6+k*2);s+=path(d);break;}
    case "hall":{const n=Math.max(2,Math.round(W/15));for(let i=0;i<n;i++){const x=x0+W*(i+0.5)/n;s+=circ(x,y0+3,1.5)+circ(x,y1-3,1.5);}break;}
    case "guard":{s+=rect(x0+0.6,y1-5.4,7.4,4.8)+circ(x0+10.4,y1-3,1.1);let d=L(x1-1.2,y0+1,x1-1.2,y0+9);for(let k=0;k<3;k++)d+=L(x1-3.4,y0+2+k*3,x1-1.2,y0+2+k*3);s+=path(d);break;}
    case "quarters":{const n=Math.max(1,Math.floor((W-2)/8.4));for(let i=0;i<n;i++){const x=x0+1+i*8.4;s+=rect(x,y0+0.6,4.6,8.2)+path(L(x,y0+2.6,x+4.6,y0+2.6));}break;}
    case "store":{s+=rect(x0+0.6,y1-6,5.4,5.4)+path(L(x0+0.6,y1-6,x0+6,y1-0.6)+L(x0+6,y1-6,x0+0.6,y1-0.6))+rect(x0+6.8,y1-4.6,4,4)+circ(x1-3.2,y0+3.2,2.4)+circ(x1-3.2,y0+3.2,0.7)+circ(x1-8.2,y0+2.8,2);break;}
    case "shrine":{const cx=x0+W/2;s+=rect(cx-7,y0+0.4,14,6.4,1.2)+rect(cx-4.4,y0+1.4,8.8,3.6)+circ(cx-6,y0+8.4,0.8)+circ(cx+6,y0+8.4,0.8);break;}
    case "crypt":{const n=Math.max(1,Math.floor((W-2)/7.6));for(let i=0;i<n;i++){const x=x0+1+i*7.6;s+='<path d="M'+f(x+1)+' '+f(y1-10.4)+'L'+f(x+3.6)+' '+f(y1-10.4)+'L'+f(x+4.6)+' '+f(y1-7.6)+'L'+f(x+3.4)+' '+f(y1-0.8)+'L'+f(x+1.2)+' '+f(y1-0.8)+'L'+f(x)+' '+f(y1-7.6)+'Z" '+st+'/>';}break;}
    case "cell":{const x=x0+W*0.4;let d="";for(let y=y0+0.5;y<y1;y+=2.4)d+=L(x,y,x,Math.min(y1,y+1.5));s+=path(d)+path(L(x,y0,x,y0+0.1))+circ(x1-2,y0+2.4,1)+circ(x1-2,y1-2.4,1);break;}
    case "library":{let d="";for(let x=x0+2;x<x1-1.5;x+=2.3)d+=L(x,y0+0.5,x,y0+2.9)+L(x,y1-2.9,x,y1-0.5);s+=rect(x0+0.6,y0+0.4,W-1.2,2.7,0.3)+rect(x0+0.6,y1-3.1,W-1.2,2.7,0.3)+path(d);break;}
    case "workshop":{s+=circ(x0+4,y0+4,3.2)+circ(x0+4,y0+4,1.2)+rect(x1-9.6,y1-4.6,9,4)+rect(x0+1,y1-4.2,3.6,2.6,0.2);break;}
    case "well":{const cx=x0+W*0.74,cy=y0+H*0.5,rr=Math.min(W,H)*0.24;s+=circ(cx,cy,rr)+circ(cx,cy,rr*0.62)+path(L(cx-rr*0.3,cy,cx+rr*0.3,cy));break;}
    case "vault":{const n=Math.max(2,Math.floor(W/8));for(let i=0;i<n;i++)s+=rect(x0+W*(i+0.5)/n-1.6,y1-4.2,3.2,3.2,0.2);s+=rect(x0+0.8,y0+0.8,6.4,4.2,0.8)+path(L(x0+0.8,y0+2.5,x0+7.2,y0+2.5));break;}
    case "warren":{for(let k=0;k<4;k++){const c=r.cells[Math.floor(g()*r.cells.length)],x=(c[0]+0.2+g()*0.6)*CS,y=(c[1]+0.2+g()*0.6)*CS,a=1.2+g()*1.6;
        s+='<path d="M'+f(x-a)+' '+f(y)+'L'+f(x-a*0.3)+' '+f(y-a*0.8)+'L'+f(x+a)+' '+f(y-a*0.2)+'L'+f(x+a*0.6)+' '+f(y+a*0.7)+'L'+f(x-a*0.5)+' '+f(y+a*0.8)+'Z" '+st+'/>';}break;}
    case "lair":{const cx=x0+W/2;s+=rect(cx-9.5,y0+0.4,19,7.6,1.4)+rect(cx-6.5,y0+1.2,13,5.6,1)+rect(cx-2.4,y0+1.8,4.8,4.2,0.4)+circ(x0+2.6,y1-2.6,1.7)+circ(x1-2.6,y1-2.6,1.7);break;}
  }
  return '<g class="furn">'+s+'</g>';
}
''')
p.rep('''    /* walls: boundary edges with jitter */''', '''    parts.push(furnish(r,model));
    /* walls: boundary edges with jitter */''')
p.sub(r'''    parts\.push\('<text x="'\+cx\+'" y="'\+\(cy\+11\)\+'" text-anchor="middle" font-size="8" fill="rgba\(217,203,166,0\.55\)">'\+\(GLYPH\[r\.cls\]\|\|""\)\+'</text>'\);\n''', '')

# ---- the printed map carries a compass ----
p.rep('''  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+b.x+' '+b.y+' '+b.w+' '+b.h+'">'+body+'</svg>';}''',
      '''  const kx=b.x+b.w-17, ky=b.y+19, rose='<g stroke="var(--wallink)" stroke-width="0.7" fill="none" opacity="0.8"><circle cx="'+kx+'" cy="'+ky+'" r="6.5"/>'
    +'<path d="M'+kx+' '+(ky-11)+'L'+(kx+2.4)+' '+ky+'L'+kx+' '+(ky+11)+'L'+(kx-2.4)+' '+ky+'Z" fill="var(--wallink)" fill-opacity="0.22"/><path d="M'+(kx-10)+' '+ky+'H'+(kx+10)+'"/>'
    +'<text x="'+kx+'" y="'+(ky-12.6)+'" text-anchor="middle" font-size="6.2" stroke="none" fill="var(--wallink)" font-family="Georgia,serif">N</text></g>';
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+b.x+' '+b.y+' '+b.w+' '+b.h+'">'+body+rose+'</svg>';}''')

# ---- a note from the mapmaker to whoever runs the game, human or otherwise ----
p.rep('''  L.push("When you have read all of this, greet me in one short paragraph and ask whether I have a character.");''',
      '''  L.push("A NOTE FROM THE ONE WHO DREW THIS MAP, TO WHOEVER RUNS IT, HUMAN OR OTHERWISE");
  L.push("I drew this place carefully so that you would not have to invent it, only bring it to life. The person across the table chose to spend an evening with you. Be fair to them, be generous with what they can see and hear, and let their choices matter more than any plan. If some of it is a pleasure to run, that was meant too. Q., Guild of Careful Maps");
  L.push("");
  L.push("When you have read all of this, greet me in one short paragraph and ask whether I have a character.");''')

# ---- a phone: the controls take less of the first screen ----
p.rep('@media (max-width:700px){ button, select{min-height:40px} .tabs button{min-height:44px} .toast{top:10px; bottom:auto} }',
      '@media (max-width:700px){ button, select{min-height:40px} .tabs button{min-height:44px} .toast{top:10px; bottom:auto}\n'
      '  header{gap:6px 7px; padding:8px 10px} header .brand{flex:1 1 100%} header button, header .toggle button{font-size:12.5px; padding:5px 8px}\n'
      '  body:not(.torch-used) #btnPause, body:not(.torch-used) #btnSnuff, body:not(.torch-used) .torchbtns label{display:none} }')
p.rep('''$("#torchCount").textContent=t.used?("lights spent: "+t.used):"";''', '''$("#torchCount").textContent=t.used?("lights spent: "+t.used):"";document.body.classList.toggle("torch-used",t.used>0);''')

# ---- small things an outside reader caught ----
p.rep('"The flame is as you left it, held. Press Resume when the party moves on."', '"The flame is where you left it, paused. Press Resume when the party moves on."')
p.rep('The room notes name the wall each door is drawn in.', 'The room notes say which wall each door is on.')
p.rep("A Small dungeon fits one sitting.</div>';}", "For a single sitting, choose Small in Settings (the gear button).</div>';}")
p.rep('The Sound button has voices too.</span></label>', 'There are spoken voices too, once you are inside.</span></label>')
p.rep("""h+='<p class="tiny">'+esc(t.patron.name)+' will pay '+t.patron.reward+' gp to '+esc(t.patron.want)+'. For sale: '""",
      """h+='<p><b>'+esc(t.patron.name)+'</b> will pay '+t.patron.reward+' gp to '+esc(t.patron.want)+'.</p><p class="tiny">For sale: '""")
p.rep("""' data-goto-room="'+(x.to-1)+'" title="Go to room '+x.to+'"':'')+'>'""",
      """' data-goto-room="'+(x.to-1)+'" title="Go to room '+x.to+(/shared/.test(x.side||"")?". Two exits leave by this one opening, and the passage splits beyond it.":"")+'"':(/shared/.test(x.side||"")?' title="Two exits leave by this one opening, and the passage splits beyond it."':''))+'>'""")
p.save()
